import CoreServices
import Foundation
// Independent FSEvents watcher on "/": prints each event under a MEVrepro folder (and any
// must-scan / dropped event) with a timestamp, to compare with when the daemon applies it.
let fmt = ISO8601DateFormatter()
fmt.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
let cb: FSEventStreamCallback = { _, _, n, paths, flags, ids in
    let ps = unsafeBitCast(paths, to: NSArray.self) as! [String]
    let special = UInt32(kFSEventStreamEventFlagMustScanSubDirs | kFSEventStreamEventFlagUserDropped
        | kFSEventStreamEventFlagKernelDropped | kFSEventStreamEventFlagRootChanged)
    for i in 0..<n where ps[i].contains("MEVrepro") || flags[i] & special != 0 {
        print("\(fmt.string(from: Date())) fsevent id=\(ids[i]) flags=0x\(String(flags[i], radix: 16)) \(ps[i])")
    }
    fflush(stdout)
}
let s = FSEventStreamCreate(nil, cb, nil, ["/"] as CFArray, FSEventStreamEventId(kFSEventStreamEventIdSinceNow), 0.3,
    FSEventStreamCreateFlags(kFSEventStreamCreateFlagUseCFTypes | kFSEventStreamCreateFlagWatchRoot))!
FSEventStreamSetDispatchQueue(s, DispatchQueue(label: "w"))
FSEventStreamStart(s)
print("\(fmt.string(from: Date())) watching")
fflush(stdout)
dispatchMain()

